// Motion Prompt #062 · MIT License (c) 2026 Shohei Ohtaki · https://showheyohtaki.github.io/motion-prompt/#062
//
// Range slider / レンジスライダー
// Pack: ui (UI component names) · element 14 · Category: Choosing & switching
// What happens: On a price slider, the left handle is dragged right and the right handle left to narrow the range, then both go back.
// Motion spec:
//   - 4.5 s cycle on a 542×191 card. Track: x 54–488, 8 tall, at y 120; the part between the two handles is blue. Range ¥0–¥10,000.
//   - Handles: white, radius 13, 3 px blue rim; while dragged, radius 15 with a light-blue halo of radius 24.
//   - Low handle: 0.1 → 0.3 (¥1,000 → ¥3,000) over 1.0–1.6 s, back over 3.55–3.9 s. High handle: 1.0 → 0.8 (¥10,000 → ¥8,000) over 2.1–2.6 s, back over 2.95–3.3 s. All easeInOutCubic.
//   - A value bubble (28 tall) above each handle, blue with white text while dragged. The range "¥1,000 – ¥10,000" is shown in blue at top right, updated in ¥100 steps.
//   - The cursor sits on the handle it drags (presses at 1.0, 2.1, 2.95 and 3.55 s).
// When to use it: Use it to filter by a range, such as price, date or size, with a minimum and a maximum.
// Tags: range-slider, slider, dual-thumb, min-max, price-filter, range
// Size: 542x191 px · Cycle: 4.5 s
// Needs: kit ui -> https://showheyohtaki.github.io/motion-prompt/api/v1/kit/ui.js
// Live demo: https://showheyohtaki.github.io/motion-prompt/#062
//
// cells[i](k, w, h, u): k = CanvasRenderingContext2D (already cleared and wrapped in save/restore by the caller), w,h = size, u = seconds in [0, cycle). The picture depends only on u.
// Element code starts here. CELLS, constants and helpers live in the kit.

// @element 14
// 14 レンジスライダー（Range slider）
CELLS[13] = ui((w, h, t) => {
  // つまみ2つで範囲を選ぶ：下限 ¥1,000→¥3,000、上限 ¥10,000→¥8,000、のち元へ戻す
  const LO = tt => .1 + .2 * eio(seg(tt, 1.0, 1.6)) - .2 * eio(seg(tt, 3.55, 3.9));
  const HI = tt => 1.0 - .2 * eio(seg(tt, 2.1, 2.6)) + .2 * eio(seg(tt, 2.95, 3.3));
  const x0 = 54, x1 = 488, ty = 120, X_ = v => lerp(x0, x1, v);
  const lo = LO(t), hi = HI(t), lx = X_(lo), hx = X_(hi);
  const yen = v => '¥' + (Math.round(v * 100) * 100).toLocaleString('en-US');
  text('価格', 24, 26, 16, '#555', 700);
  text(yen(lo) + ' 〜 ' + yen(hi), w - 24, 26, 17, C.blue, 700, 'right', NUMF);
  fillRR(x0, ty - 4, x1 - x0, 8, 4, '#e3e1df'); fillRR(lx, ty - 4, hx - lx, 8, 4, C.blue);
  const loAct = (t > 1.0 && t < 1.7) || (t > 3.55 && t < 3.95), hiAct = t > 2.1 && t < 3.3;
  [[lx, lo, loAct], [hx, hi, hiAct]].forEach(([kx, v, act]) => {
    if (act) circle(kx, ty, 24, 'rgba(31,90,232,.14)');
    shadowed(() => circle(kx, ty, act ? 15 : 13, '#fff'), 6, 2, .25); ring(kx, ty, act ? 15 : 13, C.blue, 3);
    const val = yen(v), bw = tw(val, 15, 700, NUMF) + 18, bx = clamp(kx - bw / 2, 4, w - 4 - bw);
    fillRR(bx, ty - 60, bw, 28, 7, act ? C.blue : C.lb);
    X.beginPath(); X.moveTo(kx - 6, ty - 32); X.lineTo(kx, ty - 26); X.lineTo(kx + 6, ty - 32); X.fillStyle = act ? C.blue : C.lb; X.fill();
    text(val, bx + bw / 2, ty - 46, 15, act ? '#fff' : C.blue, 700, 'center', NUMF);
  });
  text('¥0', x0, 154, 14, '#9a9896', 500, 'center', NUMF); text('¥10,000', x1 - 10, 154, 14, '#9a9896', 500, 'center', NUMF);
  bar(24, 174, 220, C.line, 8);
  const off = [w + 30, h + 30], L = tt => [X_(LO(tt)), ty + 4], Hh = tt => [X_(HI(tt)), ty + 4];
  const mv = (a, b, ta, tb) => track([[ta, a[0], a[1]], [tb, b[0], b[1]]], t);
  let pos;
  if (t < 1.0) pos = mv(off, L(1.0), .3, .95);
  else if (t < 1.7) pos = L(t);
  else if (t < 2.1) pos = mv(L(1.7), Hh(2.1), 1.7, 2.05);
  else if (t < 3.3) pos = Hh(t);
  else if (t < 3.55) pos = mv(Hh(3.3), L(3.55), 3.3, 3.52);
  else if (t < 3.95) pos = L(t);
  else pos = mv(L(3.95), off, 3.95, 4.3);
  pointer([[0, pos[0], pos[1]]], [1.0, 2.1, 2.95, 3.55], t);
});
